import{_ as a,o as s,c as e,ag as p}from"./chunks/framework.DUTPmUpA.js";const b=JSON.parse('{"title":"Преобразования","description":"","frontmatter":{"title":"Преобразования","author":"DrTeaSpoon","steamId":"76561197975484185","date":"07.09.2016"},"headers":[],"relativePath":"abilities/lua-modifiers/3.md","filePath":"abilities/lua-modifiers/3.md"}'),l={name:"abilities/lua-modifiers/3.md"};function i(t,n,r,c,o,d){return s(),e("div",null,[...n[0]||(n[0]=[p(`<h1 id="преобразования" tabindex="-1">Преобразования <a class="header-anchor" href="#преобразования" aria-label="Permalink to &quot;Преобразования&quot;">​</a></h1><p>В этом уроке я жульничаю и не объясняю, как создать способность Lua. Если вы хотите увидеть полный пример кода <a href="https://gitlab.com/DrTeaSpoon/Dota2Overflow/tree/master/game/dota_addons/dota2overflow/scripts/vscripts/lua_abilities/ultimates/metamorph" target="_blank" rel="noreferrer">click here!</a></p><p>Теперь мы сосредоточимся на модификаторе lua. Хотя мы можем выполнять преобразования и прочее в аналоге, управляемом данными, не хватает вычислений, которые заставили бы эти вещи работать лучше. Первым вопросом является дальность и тип атаки. Мы предполагаем, что наша специальная способность имеет особую ценность для <code>attack_range</code> и предназначена для трансформации существа ближнего боя. В этом примере мы используем Рошана, поэтому, чтобы дальность атаки соответствовала оригиналу, мы установили его на <code>128</code>.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function transformation_mod:OnCreated( kv )</span></span>
<span class="line"><span>    if IsServer() then</span></span>
<span class="line"><span>        self.AttackBonus = (self:GetParent():GetAttackRange() - self:GetAbility():GetSpecialValueFor(&quot;attack_range&quot;)) * -1</span></span>
<span class="line"><span>        --We get original attack range and subtract away the wanted attack range, then negate the result.</span></span>
<span class="line"><span>        --YAY Math!</span></span>
<span class="line"><span>        self.OriginalAtkCap = self:GetParent():GetAttackCapability()</span></span>
<span class="line"><span>        --Save original so we can set it back.</span></span>
<span class="line"><span>        self:GetParent():SetAttackCapability(DOTA_UNIT_CAP_MELEE_ATTACK)</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>Теперь нам нужно сделать так, чтобы при потере этого модификатора мы изменили тип атаки обратно на исходный.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function transformation_mod:OnDestroy()</span></span>
<span class="line"><span>    if IsServer() then</span></span>
<span class="line"><span>        self:GetParent():SetAttackCapability(self.OriginalAtkCap)</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Сюда следует отнести то, на что, по нашему мнению, должна повлиять трансформация, это некоторые общие моменты.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function transformation_mod:DeclareFunctions()</span></span>
<span class="line"><span>    local funcs = {</span></span>
<span class="line"><span>        MODIFIER_PROPERTY_MODEL_CHANGE,</span></span>
<span class="line"><span>        MODIFIER_PROPERTY_MODEL_SCALE,</span></span>
<span class="line"><span>        MODIFIER_PROPERTY_ATTACK_RANGE_BONUS</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return funcs</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Теперь нам нужно реализовать эти функции. Первый — для модели, второй — для дальности атаки и последний — для масштаба.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function transformation_mod:GetModifierModelChange() return &quot;models/creeps/roshan/roshan.vmdl&quot; end</span></span>
<span class="line"><span>function transformation_mod:GetModifierAttackRangeBonus() return self.AttackBonus end</span></span>
<span class="line"><span>function transformation_mod:GetModifierModelScale() return self:GetAbility():GetLevel()*0.5 end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Последние проблемы — использование способностей при иммунитете и правильное дублирование модификатора иллюзий.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function metamorphosis_mod:GetAttributes() return MODIFIER_ATTRIBUTE_IGNORE_INVULNERABLE end</span></span>
<span class="line"><span>function metamorphosis_mod:AllowIllusionDuplicate() return true end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Вот и все. Вы можете добавить эффекты частиц и/или анимацию. Хотя, обратите внимание, есть некоторые проблемы с анимацией некоторых героев. Например, анимация смерти Phantom Lancer заставляет модель игрока исчезнуть, поэтому я советую быть осторожным с выбранной анимацией.</p><p>Следующая тема: <a href="./4">Enchanting Trees</a></p>`,14)])])}const m=a(l,[["render",i]]);export{b as __pageData,m as default};
